import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-05-24 :: Ceph Code Walkthrough: RGW Multisite Replication","description":"","frontmatter":{"title":"2019-05-24 :: Ceph Code Walkthrough: RGW Multisite Replication","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","RGW","Multi","site Replication","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-24_-_-_Ceph_Code_Walkthrough_-_RGW_Multisite_Replication.md","filePath":"posts/2019/2019-05-24_-_-_Ceph_Code_Walkthrough_-_RGW_Multisite_Replication.md","lastUpdated":1780459816000}'),o={name:"posts/2019/2019-05-24_-_-_Ceph_Code_Walkthrough_-_RGW_Multisite_Replication.md"};function r(n,l,s,u,h,_){return e(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-rgw-多站点代码走查" tabindex="-1">会议主题：Ceph RGW 多站点代码走查 <a class="header-anchor" href="#会议主题-ceph-rgw-多站点代码走查" aria-label="Permalink to &quot;会议主题：Ceph RGW 多站点代码走查&quot;">​</a></h4><h4 id="主讲人-主讲人姓名" tabindex="-1">主讲人：[主讲人姓名] <a class="header-anchor" href="#主讲人-主讲人姓名" aria-label="Permalink to &quot;主讲人：[主讲人姓名]&quot;">​</a></h4><h4 id="会议时间-会议日期" tabindex="-1">会议时间：[会议日期] <a class="header-anchor" href="#会议时间-会议日期" aria-label="Permalink to &quot;会议时间：[会议日期]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>高层次概述</strong>：</p><ul><li>主讲人介绍了基于日志的复制工作原理，包括不同类型的多站点日志、读取模型和协同程序（co-routines）的工作方式。</li><li>讨论了元数据和数据同步的代码细节。</li></ul></li><li><p><strong>日志基础复制</strong>：</p><ul><li>在两个不同集群之间，每个集群上放置一个Zone，并将它们链接在一起。</li><li>当一个Zone进行更改时，它会在本地将更改写入日志，另一个Zone会从Zone读取日志并获取最新副本。</li></ul></li><li><p><strong>主要日志类型</strong>：</p><ul><li><strong>元数据日志</strong>：记录用户和桶的所有更改。</li><li><strong>桶索引日志</strong>：存储在桶索引中，记录对象的所有更改。</li><li><strong>数据更改日志</strong>：记录哪些桶及其分片有更改。</li></ul></li><li><p><strong>日志分片</strong>：</p><ul><li>这些多站点日志被分片存储在多个Rados对象中，以分散读取和写入操作，以及在同一Zone内运行的不同网关之间分散复制工作。</li></ul></li><li><p><strong>线程模型</strong>：</p><ul><li>每个源Zone都有一个元数据同步线程和一个数据同步线程。</li><li>元数据同步有一个主Zone，其他Zone只从主Zone同步。</li><li>数据同步是主动-主动模式，每个Zone都从其他Zone同步数据。</li></ul></li><li><p><strong>协同程序框架</strong>：</p><ul><li>协同程序（co-routines）用于处理多个分片并行工作，避免线程阻塞。</li><li>协同程序框架包括协同程序类、堆栈和调度管理器。</li></ul></li><li><p><strong>元数据同步</strong>：</p><ul><li>元数据同步从主Zone读取元数据日志，并将其存储在本地。</li><li>元数据同步包括全量同步和增量同步。</li></ul></li><li><p><strong>数据同步</strong>：</p><ul><li>数据同步处理数据更改日志，并启动桶同步进程。</li><li>数据同步也包括全量同步和增量同步。</li></ul></li><li><p><strong>桶同步</strong>：</p><ul><li>桶同步从其他Zone读取桶索引日志，并处理日志条目。</li><li>桶同步包括全量同步和增量同步。</li></ul></li><li><p><strong>问题与讨论</strong>：</p><ul><li>讨论了协同程序的调用方式、日志分片的管理、错误处理和重试机制。</li><li>解答了关于多部分对象处理、元数据同步的删除识别、Zone和Zone Group的配置等问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>需要对代码中的魔法数字（magic numbers）进行审查和优化。</li><li>确认了协同程序框架的设计和使用方式。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化和审查代码中的魔法数字。</li><li>深入理解协同程序框架的实现和应用。</li><li>确保多站点复制的稳定性和性能。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在预定时间内圆满结束，感谢所有参与者的积极参与和提问。</li></ul>',12)])])}const c=i(o,[["render",r]]);export{d as __pageData,c as default};
